const l06=k=>{const value=(L06[lang]||L06.en)[k]||k;return window.CouncilBridge?.connected&&['webSearch','writeNotes'].includes(k)?value.replace(/（接入后）|（接続後）| \(after connection\)/,''):value};
const defaultTools=(role)=>({readLocal:role==='context',webSearch:false,writeNotes:role==='scribe',runCode:false});
const mkAgent=(id,provider,role,name,model)=>({id,provider,role,name:name||CATALOG[provider].name,model:model||CATALOG[provider].defaults,effort:'default',enabled:true,tools:defaultTools(role)});
function ensureRoster(s){
 if(!Array.isArray(s.agentRoster)){
  s.agentRoster=(s.selected||['claude','codex']).filter(p=>CATALOG[p]||['claude','codex','gemini','grok'].includes(p)).map(p=>mkAgent(p,p,'debater',CATALOG[p]?.name||p,s.config?.[p]?.model));
  for(const a of s.agentRoster)a.effort=s.config?.[a.id]?.effort||'default';
  s.agentRoster.push({...mkAgent('utility-context-'+s.id,'codex','context','Context Agent','default'),enabled:s.contextPreparation!=='optional'});
  s.agentRoster.push(mkAgent('utility-scribe-'+s.id,'claude','scribe','Scribe Agent','claude-sonnet-4-6'));
 }
 for(const a of s.agentRoster){
  if(typeof a.rules!=='string')a.rules='';
  if(!a.tools)a.tools=defaultTools(a.role);
  if(!a.model)a.model=CATALOG[a.provider]?.defaults||'default';
  if(!a.effort)a.effort='default';
  if(a.enabled===undefined)a.enabled=true;
 }
}
function refreshInstances(s){
 ensureRoster(s);
 for(const a of s.agentRoster){
  const source=CATALOG[a.provider];if(!source)continue;
  CATALOG[a.id]={...source,name:a.name,role:a.role};LOGO_DATA[a.id]=LOGO_DATA[a.provider];
  for(const code of ['zh','ja','en']){if(demo[code][a.provider])demo[code][a.id]=demo[code][a.provider];if(ROLE_LABELS[code])ROLE_LABELS[code][a.id]=(L06[code]||L06.en)[a.role];}
  s.config[a.id]={model:a.model,effort:a.effort};
 }
}
