$('fixedFlowWrap').appendChild(document.querySelector('.flowbar'));
const syncPinnedHeading=()=>{
 const wrap=$('fixedFlowWrap'), y=$('scroll').scrollTop;
 if(S().view!=='debate')return wrap.classList.remove('compact');
 // Hysteresis keeps the compact header stable around the scroll boundary.
 const compact=wrap.classList.contains('compact');
 // Short records must not oscillate between full and compact headers when
 // a height change clamps scrollTop back to zero.
 const room=$('scroll').scrollHeight-$('scroll').clientHeight;
 if(!compact&&y>=90&&room>wrap.offsetHeight+120)wrap.classList.add('compact');
 else if(compact&&y<=12)wrap.classList.remove('compact');
};
$('scroll').addEventListener('scroll',syncPinnedHeading,{passive:true});
